import Avatar from 'flarum/common/components/Avatar';
import classList from 'flarum/common/utils/classList';
import humanTime from 'flarum/common/helpers/humanTime';
import { t, tx } from '../util';

/** A 9:16 card: the photo, the first frame of a video, or the text on its colour, with the author. */
export function storyCard(story, onopen, footer) {
  const user = story.user();
  return m("article", {
    className: classList('GlimpseCard', story.isSeen() && 'is-seen')
  }, m("button", {
    type: "button",
    className: "GlimpseCard-open",
    onclick: onopen,
    "aria-label": tx('page.open', {
      name: user ? user.displayName() : ''
    })
  }, m("span", {
    className: classList('GlimpseCard-media', story.kind() === 'text' && `GlimpseText GlimpseBg-${story.background() ?? 0}`)
  }, story.kind() === 'text' ? m("span", {
    className: "GlimpseText-body"
  }, story.text()) : story.kind() === 'video' ? m("video", {
    src: `${story.mediaUrl()}#t=0.1`,
    preload: "metadata",
    muted: true,
    playsinline: true,
    "aria-hidden": "true"
  }) : m("img", {
    src: story.mediaUrl(),
    alt: "",
    loading: "lazy",
    decoding: "async"
  })), story.kind() === 'video' && story.durationMs() ? m("span", {
    className: "GlimpseCard-duration"
  }, m("i", {
    className: "fas fa-play",
    "aria-hidden": "true"
  }), " ", Math.round((story.durationMs() || 0) / 1000), "s") : null, user ? m("span", {
    className: "GlimpseCard-who"
  }, m(Avatar, {
    user: user
  }), m("span", null, m("span", {
    className: "GlimpseCard-name"
  }, user.displayName()), m("span", {
    className: "GlimpseCard-time"
  }, humanTime(story.createdAt())))) : null), status(story) ? m("p", {
    className: "GlimpseCard-status"
  }, status(story)) : null, footer ? m("div", {
    className: "GlimpseCard-foot"
  }, footer) : null);
}

/** What a story's author (or a moderator) needs to know that a viewer never sees. */
function status(story) {
  if (story.status() === 'pending') return t('profile.pending');
  if (story.status() === 'hidden') return t('profile.hidden');
  const expires = story.expiresAt();
  return expires && expires.getTime() < Date.now() ? t('profile.kept') : null;
}
flarum.reg.add('ernestdefoe-glimpse', 'forum/ui/card', { storyCard: storyCard, });