/**
 * The profile tab. UserPage lives in core's lazy chunk, so this small subclass is made once it has
 * loaded; the tab itself is ProfileStories.
 */
export async function userStoriesPage() {
  if (made) return made;
  const UserPage = defaultExport(await runtime().reg.asyncModuleImport('flarum/forum/components/UserPage'));
  made = class UserStoriesPage extends UserPage {
    oninit(vnode) {
      super.oninit(vnode);
      this.loadUser(m.route.param('username'));
    }
    content() {
      return this.user ? m(ProfileStories, {
        key: this.user.id(),
        user: this.user
      }) : null;
    }
  };
  return made;
}
