import Viewer from './Viewer';
import { whenSeenSaved } from './viewerTools';
let mounted = null;

/** Opens the viewer over the page. One at a time. */
export function openViewer(options) {
  closeViewer();
  mounted = document.createElement('div');
  mounted.className = 'GlimpseViewer-root';
  document.body.appendChild(mounted);
  const close = () => {
    // Removing the viewer flushes its last seen marks; onclose (the bar's reload) runs once they are saved.
    closeViewer();
    whenSeenSaved().then(() => {
      options.onclose?.();
      m.redraw();
    });
  };
  m.mount(mounted, {
    view: () => m(Viewer, {
      options: options,
      close: close
    })
  });
}
export function closeViewer() {
  if (!mounted) return;
  m.mount(mounted, null);
  mounted.remove();
  mounted = null;
}
flarum.reg.add('ernestdefoe-glimpse', 'forum/ui/mount', { openViewer: openViewer,closeViewer: closeViewer, });